<template>
  <div class="settings-toggle-item">
    <div class="settings-toggle-content">
      <span class="settings-toggle-label">{{ $t('ocr_setting_etext') }}</span>
    </div>
    <div class="settings-toggle-actions">
      <f-toggle size="xs"
        v-model="user_settings[use_etext_if_available]"
        @update:model-value="(val: any) => save_org_pref(use_etext_if_available, val)"
      />
    </div>
  </div>

  <div class="settings-toggle-item">
    <div class="settings-toggle-content">
      <span class="settings-toggle-label">
        {{ $t('use_deskew_if_available') }}
        <q-icon name="help_outline" size="xs" class="help-sign cursor-pointer q-ml-xs">
          <q-tooltip><div style="max-width: 400px">{{ $t('use_deskew_info') }}</div></q-tooltip>
        </q-icon>
      </span>
    </div>
    <div class="settings-toggle-actions">
      <f-toggle size="xs"
        v-model="user_settings[deskew_document]"
        @update:model-value="(val: any) => save_org_pref(deskew_document, val)"
      />
    </div>
  </div>

  <div class="settings-toggle-item">
    <div class="settings-toggle-content">
      <span class="settings-toggle-label">{{ $t('ai_ocr_version') }}</span>
    </div>
    <div class="settings-toggle-actions">
      <q-select
        outlined
        dense
        class="s-field back-white"
        style="min-width: 160px;"
        v-model="user_settings[ai_ocr_version]"
        :options="aiOcrVersionList"
        @update:model-value="(val: any) => save_org_pref(ai_ocr_version, val)"
        emit-value
        map-options
      />
    </div>
  </div>

  <q-inner-loading :showing="processing">
    <img class="loading-image" src="/images/loader.gif" alt="Loading..." />
  </q-inner-loading>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { storeToRefs } from 'pinia';
import { CONSTANTS } from 'src/constants';
import { defineComponent, ref } from 'vue';
import type { dynamicObj } from 'src/pages/assets';
import { useSettingStore } from 'src/store/main';
import { ApiExceptions } from 'src/exceptions/index';
export default defineComponent({
  el: '#app',
  components: {},
    data() {
    return {
      ai_ocr_version: CONSTANTS.ai_ocr_version,
      deskew_document: CONSTANTS.deskew_document,
      use_etext_if_available: CONSTANTS.use_etext_if_available,
    };
  },
  setup() {
    const settings_store = useSettingStore();
    const { user_settings, loading_settings } = storeToRefs(settings_store);
    const { updateSetting } = settings_store;

    return {
      updateSetting,
      user_settings,
      loading_settings,
      USE_ETEXT_IF_AVAILABLE: ref(false),
      DESKEW_DOCUMENT: ref(false),
      AI_OCR_VERSION_MODEL: ref('1.2'),
      processing: ref(false),
      aiOcrVersionList: [
        {
          label: '1_2',
          value: '1.2',
        },
        {
          label: '2_0',
          value: '2.0',
        },
        {
          label: '2_1',
          value: '2.1',
        },
      ],
    };
  },
  watch: {
    loading_settings: {
      handler: function (newVal, oldVal) {
        if (newVal == false && oldVal == true) {
          this.processing = false;
          this.setDefaultSettings();
        } else {
          this.processing = true;
        }
      },
    },
  },
  beforeRouteLeave: function (to: any, from: any, next: any) {
    next();
  },
  mounted: function () {
    this.setDefaultSettings();
  },
  methods: {
    async save_org_pref(key: string, value: boolean) {
      try {
        this.processing = true;

        await this.updateSetting(key, value);
        notify.success(this.$t('MSG_SAVE'));
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.processing = false;
      }
    },

    setDefaultSettings() {
      if (!this.user_settings[this.deskew_document]) {
        this.user_settings[this.deskew_document] = false;
      }

      if (!this.user_settings[this.use_etext_if_available]) {
        this.user_settings[this.use_etext_if_available] = false;
      }
      if (!this.user_settings[this.ai_ocr_version]) {
        this.user_settings[this.ai_ocr_version] = '1.2';
      }
    },
  },
});
</script>
<style scoped></style>
