<template>
  <div class="settings-toggle-item">
    <div class="settings-toggle-content">
      <span class="settings-toggle-label">{{ $t('ocr_setting_info') }}</span>
    </div>
  </div>

  <div class="ocr-slider-section">
    <q-slider
      v-model="ocr_check['OCR_PERCENTAGE']"
      :min="0"
      :max="100"
      color="primary"
      label-always
      :markers="5"
      :marker-labels="arrayMarkerLabel"
      @change="
        (val: any) => {
          save_org_pref(percent_name, val);
        }
      "
    />
  </div>

  <div class="settings-toggle-item">
    <div class="settings-toggle-content">
      <span class="settings-toggle-label">{{ $t('ocr_setting_quality_lower') }}</span>
    </div>
    <div class="settings-toggle-actions">
      <q-select
        v-model="ocr_check['OCR_TODO']"
        :options="to_do_list"
        class="s-field back-white"
        style="min-width: 220px;"
        dense
        outlined
        @update:model-value="
          (val: any) => {
            save_org_pref(task_name, val.value);
          }
        "
      />
    </div>
  </div>
</template>

<script lang="ts">
// @ts-nocheck
import { notify } from 'src/components/notifications/notify';
import { i18n } from 'src/boot/i18n';
import { defineComponent, ref } from 'vue';
import { ApiExceptions } from 'src/exceptions/index';
import type { dynamicObj } from 'src/pages/assets';
import { useSettingStore } from 'src/store/main';
export default defineComponent({
  el: '#app',
  
  setup() {
    const settings_store = useSettingStore();
    const { getOrgBasedSettings, updateSetting } = settings_store;

    let ocr_check = {} as { [k: string]: any };
    let epdf: any;
    return {
      getOrgBasedSettings,
      updateSetting,
      arrayMarkerLabel: [
        { value: 10, label: '10%' },
        { value: 20, label: '20%' },
        { value: 30, label: '30%' },
        { value: 40, label: '40%' },
        { value: 50, label: '50%' },
        { value: 60, label: '60%' },
        { value: 70, label: '70%' },
        { value: 80, label: '80%' },
        { value: 90, label: '90%' },
        { value: 100, label: '100%' },
      ],
      to_do_list: [
        { value: 'run', label: i18n.t('run_anyway') },
        { value: 'check', label: i18n.t('run_again_after_confirmation') },
        { value: 'stop', label: i18n.t('throw_error') },
      ],
      display_data: [],
      ocr_check: ref(ocr_check),
      epdf: ref(epdf),
      icon: ref(false),
      processing: ref(false),
    };
  },
  mounted() {
    this.initView();
  },
  data() {
    return {
      percent_name: 'OCR_PERCENTAGE',
      task_name: 'OCR_TODO',
      default_percent: '75',
      default_todo: 'check',
    };
  },
  methods: {
    async initView() {
      await this.getData();
      this.setDefaultValues();
      this.setOCRTodo();
    },

    async getData() {
      const response = await this.getOrgBasedSettings(this.percent_name);
      if (response != undefined) {
        this.ocr_check[this.percent_name] = response;
      }

      const response2 = await this.getOrgBasedSettings(this.task_name);
      if (response2 != undefined) {
        this.ocr_check[this.task_name] = response2;
      }
    },

    setDefaultValues() {
      if (!this.ocr_check.hasOwnProperty(this.percent_name)) {
        this.ocr_check[this.percent_name] = '75';
        this.save_org_pref(this.percent_name, '75');
      }
      if (!this.ocr_check.hasOwnProperty(this.task_name)) {
        this.ocr_check[this.task_name] = 'check';
        this.save_org_pref(this.task_name, 'check');
      }
    },

    setOCRTodo() {
      for (const [key, value] of Object.entries(this.to_do_list)) {
        if (this.ocr_check[this.task_name] == value.value) {
          this.ocr_check[this.task_name] = value.label;
        }
      }
    },

    async save_org_pref(key: string, value: string) {
      try {
        this.processing = true;
        await this.updateSetting(key, value);
        notify.success(this.$t('MSG_SAVE'));
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.processing = false;
      }
    },
  },
});
</script>
<style scoped>
.ocr-slider-section {
  padding: 2.5rem 1rem 1.5rem;
}
</style>
