<template>
  <div class="ocr-note-banner">
    <q-icon name="info" size="xs" class="q-mr-sm" />
    <span>{{ $t('note') }} {{ $t('note_ocr_header_fields') }} — {{ $t('use_rules_extraction') }} → {{ $t('use_ai_extraction') }}</span>
  </div>

  <div class="settings-toggle-item">
    <div class="settings-toggle-content">
      <span class="settings-toggle-label">
        {{ $t('use_rules_extraction') }}
        <q-icon name="help_outline" size="xs" class="help-sign cursor-pointer q-ml-xs">
          <q-tooltip><div style="max-width: 400px">{{ $t('use_rules_extraction_info') }}</div></q-tooltip>
        </q-icon>
      </span>
    </div>
    <div class="settings-toggle-actions">
      <f-toggle size="xs"
        v-model="user_settings[use_rules_extraction]"
        @update:model-value="(val: any) => save_org_pref(use_rules_extraction, val)"
      />
    </div>
  </div>

  <div class="settings-toggle-item">
    <div class="settings-toggle-content">
      <span class="settings-toggle-label">
        {{ $t('use_ai_extraction') }}
        <q-icon name="help_outline" size="xs" class="help-sign cursor-pointer q-ml-xs">
          <q-tooltip><div style="max-width: 400px">{{ $t('use_ai_extraction_info') }}</div></q-tooltip>
        </q-icon>
      </span>
    </div>
    <div class="settings-toggle-actions">
      <f-toggle size="xs"
        v-model="user_settings[use_ai_extraction]"
        @update:model-value="(val: any) => save_org_pref(use_ai_extraction, val)"
      />
    </div>
  </div>

  <q-inner-loading :showing="processing">
    <img class="loading-image" src="/images/loader.gif" alt="Loading..." />
  </q-inner-loading>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { storeToRefs } from 'pinia';
import { CONSTANTS } from 'src/constants';
import { defineComponent, ref } from 'vue';
import type { dynamicObj } from 'src/pages/assets';
import { useSettingStore } from 'src/store/main';
import { ApiExceptions } from 'src/exceptions/index';
export default defineComponent({
  el: '#app',
  components: {},
    data() {
    return {
      use_rules_extraction: CONSTANTS.use_rules_extraction,
      use_ai_extraction: CONSTANTS.use_ai_extraction,
    };
  },
  watch: {
    loading_settings: {
      handler: function (newVal, oldVal) {
        if (newVal == false && oldVal == true) {
          this.processing = false;
          this.setDefaultSettings();
        } else {
          this.processing = true;
        }
      },
    },
  },
  mounted() {
    this.setDefaultSettings();
  },
  setup() {
    const settings_store = useSettingStore();
    const { user_settings, loading_settings } = storeToRefs(settings_store);
    const { getOrgBasedSettings, updateSetting } = settings_store;
    return {
      getOrgBasedSettings,
      user_settings,
      loading_settings,
      updateSetting,
      processing: ref(false),
    };
  },
  methods: {
    setDefaultSettings() {
      if (!this.user_settings[this.use_rules_extraction]) {
        this.user_settings[this.use_rules_extraction] = false;
      }

      if (!this.user_settings[this.use_ai_extraction]) {
        this.user_settings[this.use_ai_extraction] = false;
      }
    },
    async save_org_pref(key: string, value: boolean) {
      try {
        this.processing = true;

        await this.updateSetting(key, value);
        notify.success(this.$t('MSG_SAVE'));
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.processing = false;
      }
    },
  },
});
</script>
