.ocr-note-banner {
  display: flex;
  align-items: center;
  padding: 0.5rem 1rem;
  margin: 0 1rem 0.25rem;
  background: rgba(198, 40, 40, 0.08);
  border-radius: 0.375rem;
  font-size: 0.8125rem;
  font-weight: 500;
  color: var(--q-negative);
}
